# ================================================================ SCENES
# ---- OSI ↔ TCP/IP
OSI = ["Прикладной", "Представления", "Сеансовый", "Транспортный", "Сетевой", "Канальный", "Физический"]
def _osi():
    b, els = [], {}
    b.append('<text class="zl" x="40" y="28">Модель OSI</text><text class="zl" x="560" y="28">Модель TCP/IP</text>')
    for i, t in enumerate(OSI):
        y = 44 + i * 62
        b.append(f'<g class="hbx" data-id="o{i}"><path class="hb" d="M50 {y}H330V{y+42}L320 {y+52}H40V{y+10}Z"/>'
                 f'<text class="hbt" x="72" y="{y+32}">{7-i}</text><text class="hbt" x="104" y="{y+32}">{t}</text></g>')
    tcp = [("Уровень приложений", 44, 176), ("Транспортный", 230, 52), ("Интернет", 292, 52), ("Сетевого доступа", 354, 114)]
    for j, (t, y, h) in enumerate(tcp):
        b.append(f'<g class="hbx" data-id="t{j}"><path class="hb" d="M570 {y}H850V{y+h-10}L840 {y+h}H560V{y+10}Z"/>'
                 f'<text class="hbt" x="705" y="{y+h/2+6}" text-anchor="middle">{t}</text></g>')
    for i in range(3):
        y = 44 + i * 62 + 26
        b.append(arrow(f"oa{i}", 336, y, 552, 44 + 88 + (i - 1) * 40, "teal"))
    b.append(arrow("oa3", 336, 44 + 3 * 62 + 26, 552, 256, "ice"))
    b.append(arrow("oa4", 336, 44 + 4 * 62 + 26, 552, 318, "ice"))
    b.append(arrow("oa5", 336, 44 + 5 * 62 + 26, 552, 400, "ice"))
    b.append(arrow("oa6", 336, 44 + 6 * 62 + 26, 552, 430, "ice"))
    els = {"o0": {"c": {0: "", 1: "hot", 4: "hot"}}, "o1": {"c": {0: "", 2: "hot", 4: "hot"}}, "o2": {"c": {0: "", 3: "hot", 4: "hot"}},
           "t0": {"c": {0: "", 4: "hot"}}, "oa0": {"c": {0: "", 4: "on"}}, "oa1": {"c": {0: "", 4: "on"}}, "oa2": {"c": {0: "", 4: "on"}},
           "oa3": {"c": {0: "", 5: "on old"}}, "oa4": {"c": {0: "", 5: "on old"}}, "oa5": {"c": {0: "", 5: "on old"}}, "oa6": {"c": {0: "", 5: "on old"}},
           "ocp": {"t": {0: "", 1: "7. Прикладной уровень OSI — обмен данными между приложениями пользователей",
                         2: "6. Уровень представления — формат, кодировка, сжатие, шифрование", 3: "5. Сеансовый уровень — установление, поддержание и завершение сеанса",
                         4: "Три верхних уровня OSI соответствуют одному уровню приложений TCP/IP", 5: "Остальные уровни OSI отображаются на нижние уровни TCP/IP"}}}
    sc = scene("osi", 5, els, {i: 1500 for i in range(6)})
    return (f'<div class="card dgc flow" {sc}><svg class="dg" viewBox="0 0 880 490" role="img">{"".join(b)}</svg>'
            f'<div class="fcap"><span class="fct" data-id="ocp"></span></div></div>')
OSI_SC = _osi()

