# ---- продление аренды
def _lease():
    x0, x1 = 70, 850
    T0, T1 = x0 + (x1 - x0) * .5, x0 + (x1 - x0) * .875
    b = [f'<line class="ax" x1="{x0}" y1="150" x2="{x1}" y2="150"/>',
         f'<rect class="lbar" x="{x0}" y="138" width="{x1 - x0}" height="24"/>',
         f'<text class="zl" x="{x0}" y="196">получение адреса</text><text class="zl" x="{x1}" y="196" text-anchor="end">истечение аренды</text>',
         f'<line class="tmk" x1="{T0}" y1="118" x2="{T0}" y2="182"/><text class="tml" x="{T0}" y="108" text-anchor="middle">T0 = 50 %</text>',
         f'<line class="tmk" x1="{T1}" y1="118" x2="{T1}" y2="182"/><text class="tml" x="{T1}" y="108" text-anchor="middle">T1 = 87,5 %</text>',
         f'<g class="an" data-id="lm" style="--md:1400ms"><path class="lmk" d="M0 120l10 -16h-20z M0 124V176"/></g>']
    ev = [("e1", T0, "DHCPREQUEST — одноадресно", "wb"), ("e2", T0, "DHCPACK — аренда продлена, таймеры сброшены", "wg"),
          ("e3", T0, "DHCPREQUEST — ответа нет", "wr"), ("e4", T1, "DHCPREQUEST — широковещательно", "wa"), ("e5", x1, "DHCPDISCOVER — всё заново", "wr")]
    for i, (eid, x, t, c) in enumerate(ev):
        y = 250 + (i % 3) * 44
        anc = "end" if x > 600 else "middle"
        b.append(f'<g class="an ml {c}" data-id="{eid}"><line class="evl {c}" x1="{x}" y1="166" x2="{x}" y2="{y - 20}"/><text class="mlab" x="{x}" y="{y}" text-anchor="{anc}">{t}</text></g>')
    els = {"lm": {"p": {0: (x0, 0), 1: (T0, 0), 2: (x0, 0), 3: (T0, 0), 4: (T1, 0), 5: (x1, 0)}},
           "e1": {"o": {0: 0, 1: 1, 2: 1, 3: 0}}, "e2": {"o": {0: 0, 2: 1, 3: 0}}, "e3": {"o": {0: 0, 3: 1}}, "e4": {"o": {0: 0, 4: 1}}, "e5": {"o": {0: 0, 5: 1}},
           "lcp": {"t": {0: "", 1: "1) Наступает T0: клиент отправляет DHCPREQUEST серверу, который выдал адрес, — одноадресной рассылкой.",
                         2: "Сервер работает и готов продлить аренду: DHCPACK, временные ограничения сброшены, клиент обновляет таймеры T0 и T1.",
                         3: "Другой случай: при T0 ответа не поступило. Клиент продолжает использовать адрес до T1.",
                         4: "2) После T1 и до истечения срока DHCPREQUEST уходит широковещательно — вдруг у сервера просто сменился IP-адрес.",
                         5: "3) Сервер так и не ответил (или прислал DHCPNACK): клиент начинает получение адреса заново — широковещательный DHCPDISCOVER."}},
           "lsn": {"t": {0: "", 1: "01 / 05", 2: "02 / 05", 3: "03 / 05", 4: "04 / 05", 5: "05 / 05"}}}
    sc = scene("lease", 5, els, {i: 2800 for i in range(6)})
    return (f'<div class="card dgc flow" {sc}><svg class="dg" viewBox="0 0 900 380" role="img">{"".join(b)}</svg>'
            f'<div class="fcap"><span class="fsn mono" data-id="lsn"></span><span class="fct" data-id="lcp"></span></div></div>')
LEASE = _lease()

